{
  "title": "夜探客栈",
  "scene": "夜色深沉，你潜入一座古旧的客栈。月光透过破损的窗户洒在一条狭窄的走廊上，两旁的房间门窗半掩，偶尔传来低语声。走廊尽头的房间门紧闭，门外有两名守卫在低声交谈，似乎在商量着什么。你记得江湖传闻，这家客栈是一处秘密交易的地点，门派恩怨常在此处爆发。你决定先观察四周，也许能发现一些有用的信息。突然，一阵风吹过，走廊一侧的墙角处，阴影中似乎有条小径通向后院。",
  "goal": "获取房间内的秘密情报",
  "clue": "墙角的阴影中的小径",
  "choices": [
    {
      "id": "A",
      "text": "正面攻击守卫",
      "outcome": "你猛地出手，但两名守卫训练有素，迅速反击。虽然你最终击败了他们，但走廊尽头的房门突然打开，里面的人听到动静，立即逃走。你只找到了一些散落的文件，但关键情报已经不在。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "潜入后院",
      "outcome": "你沿着墙角的阴影中的小径潜入后院，发现一道未关紧的后门。你小心翼翼地推开，进入房间，找到了一张详细记录门派恩怨和秘密交易的情报。但你不小心碰到了一个机关，触发了警报。你迅速逃离，但还是被客栈中的人发现了踪迹。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "观察守卫对话",
      "outcome": "你躲在暗处，仔细听守卫的对话。他们提到后院有一条秘密通道可以进入房间，但需要轻功才能不被发现。你利用这一线索，施展轻功悄无声息地进入后院，从秘密通道进入房间，成功获取了全部情报，未被发现。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
